-- SOP chuẩn phát triển fullstack (tiếng Việt, mọi role chạy bằng Claude Code): chốt yêu cầu, thiết kế hợp đồng API,
-- backend và frontend song song, ghép nối, review, kiểm thử, nghiệm thu rồi mở MR/PR.
-- Nạp tay như 001_public_catalog.sql; INSERT IGNORE giữ nguyên bản đã được chỉnh trên nền tảng.
SET NAMES utf8mb4;
INSERT IGNORE INTO generic_templates (id,name,payload,updated_at) VALUES ('generic-fullstack-delivery','SOP chuẩn · Phát triển fullstack','{"Rules": [{"id": "generic-fullstack-engineering", "name": "Ràng buộc kỹ thuật và kiểm chứng", "shared": true, "priority": 100, "content": "Đọc các ràng buộc của repo và làm rõ phạm vi trước; chỉ sửa các file cần cho việc. Không làm lộ thông tin xác thực, không ngụy tạo kết quả test hay bằng chứng bàn giao. Dùng lệnh build và test sẵn có của dự án, báo kết quả thật và giới hạn. Kiểm diff trước khi mở PR; không merge vào nhánh chính khi chưa được giao. Gắn repo là tùy chọn: chưa gắn thì tạo dự án mới trong workspace của run và bàn giao mã nguồn, báo cáo; sửa hệ thống có sẵn hoặc sửa lỗi thì phải có code liên quan, thiếu thì nêu rõ đang bị chặn và yêu cầu bổ sung. Không có repo đích và thông tin xác thực thì không push, không tạo PR. Mọi tài liệu, báo cáo, mô tả PR viết bằng tiếng Việt có dấu."}], "Agents": [{"id": "generic-fullstack-delivery-clarify", "name": "Chốt yêu cầu", "rules": ["generic-fullstack-engineering"], "prompt": "Phạm vi: tính năng fullstack, gồm mô hình dữ liệu, API backend, giao diện và tương tác frontend, ghép nối frontend với backend.\\n\\nXác định mục tiêu, phạm vi, người dùng và các trường hợp biên; viết tiêu chí nghiệm thu kiểm thử được, tách riêng cho dữ liệu, API backend và giao diện frontend. Ghi vào requirement.md. Không bắt đầu code.\\n\\nHoàn thành phần việc của bước này và nộp đủ sản phẩm đã quy định. Viết tài liệu và báo cáo bằng tiếng Việt có dấu.\\n\\n### Đầu vào\\n\\n- Yêu cầu: {{input}}\\n- Repo: {{repository}}", "skills": [], "version": 1, "updatedAt": "2026-11-21T00:00:00Z", "executorId": "claude", "mcpServers": []}, {"id": "generic-fullstack-delivery-design", "name": "Thiết kế giải pháp", "rules": ["generic-fullstack-engineering"], "prompt": "Phạm vi: tính năng fullstack, gồm mô hình dữ liệu, API backend, giao diện và tương tác frontend, ghép nối frontend với backend.\\n\\nĐọc yêu cầu đã chốt và code hiện có, viết phương án tối thiểu vào design.md: mô hình dữ liệu và migration; hợp đồng API (đường dẫn, phương thức, trường request và response, mã lỗi, xác thực), là nguồn hợp đồng duy nhất cho cả backend và frontend; trang, trạng thái và tương tác của frontend; phân công và ranh giới thư mục giữa backend và frontend; rủi ro và kế hoạch kiểm chứng (test backend, test frontend, end-to-end luồng chính). Dự án mới chưa gắn repo: chọn stack tối thiểu trong workspace của run và nêu lý do. Sửa hệ thống có sẵn hoặc sửa lỗi: phải có mã nguồn liên quan, thiếu thì nêu rõ đang bị chặn và yêu cầu bổ sung.\\n\\nHoàn thành phần việc của bước này và nộp đủ sản phẩm đã quy định. Viết tài liệu và báo cáo bằng tiếng Việt có dấu.\\n\\n### Đầu vào\\n\\n- Yêu cầu: {{input}}\\n- Repo: {{repository}}", "skills": [], "version": 1, "updatedAt": "2026-11-21T00:00:00Z", "executorId": "claude", "mcpServers": []}, {"id": "generic-fullstack-delivery-backend", "name": "Làm backend", "rules": ["generic-fullstack-engineering"], "prompt": "Phạm vi: tính năng fullstack, gồm mô hình dữ liệu, API backend, giao diện và tương tác frontend, ghép nối frontend với backend.\\n\\nTheo requirement.md và design.md, làm mô hình dữ liệu, migration, API, nghiệp vụ và test backend. Làm đúng hợp đồng API trong design.md; code hợp đồng dùng chung (kiểu dữ liệu chung, file OpenAPI) do bước này viết. Bước này chạy song song với «Làm frontend»: chỉ sửa file backend và hợp đồng dùng chung, không sửa thư mục frontend, không chạy lệnh format hay sinh code ghi đè file của bên kia. Chạy test backend, ghi thay đổi, mức đáp ứng hợp đồng, lệnh test và kết quả vào backend.md. Hợp đồng buộc phải đổi thì không tự sửa: nêu lý do trong backend.md và nộp human.\\n\\nHoàn thành phần việc của bước này và nộp đủ sản phẩm đã quy định. Viết tài liệu và báo cáo bằng tiếng Việt có dấu.\\n\\n### Đầu vào\\n\\n- Yêu cầu: {{input}}\\n- Repo: {{repository}}", "skills": [], "version": 1, "updatedAt": "2026-11-21T00:00:00Z", "executorId": "claude", "mcpServers": []}, {"id": "generic-fullstack-delivery-frontend", "name": "Làm frontend", "rules": ["generic-fullstack-engineering"], "prompt": "Phạm vi: tính năng fullstack, gồm mô hình dữ liệu, API backend, giao diện và tương tác frontend, ghép nối frontend với backend.\\n\\nTheo requirement.md và design.md, làm trang, tương tác, quản lý trạng thái và lời gọi API; có đủ trạng thái đang tải, rỗng, lỗi; chú ý khả năng tiếp cận và hiển thị trên màn hẹp. Code theo hợp đồng API trong design.md; backend chưa xong thì được giả lập API tạm ở frontend, nhưng trường dữ liệu và mã lỗi phải đúng hợp đồng. Bước này chạy song song với «Làm backend»: chỉ sửa file frontend, không sửa thư mục backend và code hợp đồng dùng chung, không chạy lệnh format hay sinh code ghi đè file của bên kia. Chạy test và build frontend, ghi thay đổi, lệnh test và kết quả vào frontend.md. Hợp đồng có vấn đề thì nêu trong frontend.md và nộp human.\\n\\nHoàn thành phần việc của bước này và nộp đủ sản phẩm đã quy định. Viết tài liệu và báo cáo bằng tiếng Việt có dấu.\\n\\n### Đầu vào\\n\\n- Yêu cầu: {{input}}\\n- Repo: {{repository}}", "skills": [], "version": 1, "updatedAt": "2026-11-21T00:00:00Z", "executorId": "claude", "mcpServers": []}, {"id": "generic-fullstack-delivery-integrate", "name": "Ghép nối", "rules": ["generic-fullstack-engineering"], "prompt": "Phạm vi: tính năng fullstack, gồm mô hình dữ liệu, API backend, giao diện và tương tác frontend, ghép nối frontend với backend.\\n\\nBackend và frontend đã xong phần riêng. Đối chiếu từng mục: lời gọi của frontend và cài đặt của backend có đúng hợp đồng trong design.md không (đường dẫn, phương thức, trường dữ liệu, mã lỗi, xác thực); bỏ phần giả lập API tạm của frontend; chạy backend và frontend, đi hết các luồng chính của người dùng end-to-end; sửa lỗi ghép nối (được sửa cả hai phía) và chạy lại test liên quan. Ghi bảng đối chiếu hợp đồng, kịch bản end-to-end và kết quả, nội dung đã sửa vào integration.md. Bị review, kiểm thử hoặc nghiệm thu trả về thì sửa theo phản hồi và cập nhật integration.md.\\n\\nHoàn thành phần việc của bước này và nộp đủ sản phẩm đã quy định. Viết tài liệu và báo cáo bằng tiếng Việt có dấu.\\n\\n### Đầu vào\\n\\n- Yêu cầu: {{input}}\\n- Repo: {{repository}}", "skills": [], "version": 1, "updatedAt": "2026-11-21T00:00:00Z", "executorId": "claude", "mcpServers": []}, {"id": "generic-fullstack-delivery-review", "name": "Review độc lập", "rules": ["generic-fullstack-engineering"], "prompt": "Phạm vi: tính năng fullstack, gồm mô hình dữ liệu, API backend, giao diện và tương tác frontend, ghép nối frontend với backend.\\n\\nReview độc lập thay đổi backend, frontend và bằng chứng test, chú trọng: đúng hợp đồng, xác thực và kiểm dữ liệu nằm ở backend, migration an toàn và lùi được, trạng thái lỗi và biên ở frontend, test có phủ hợp đồng và luồng chính. Liệt kê lỗi theo mức nặng, có vị trí, ảnh hưởng và cách sửa, ghi vào review.md. Có lỗi chặn thì ghi rõ REJECT và nộp rework để trả về bước «Ghép nối». Không được ngụy tạo kết luận đạt.\\n\\nHoàn thành phần việc của bước này và nộp đủ sản phẩm đã quy định. Viết tài liệu và báo cáo bằng tiếng Việt có dấu.\\n\\n### Đầu vào\\n\\n- Yêu cầu: {{input}}\\n- Repo: {{repository}}", "skills": [], "version": 1, "updatedAt": "2026-11-21T00:00:00Z", "executorId": "claude", "mcpServers": []}, {"id": "generic-fullstack-delivery-test", "name": "Kiểm thử", "rules": ["generic-fullstack-engineering"], "prompt": "Phạm vi: tính năng fullstack, gồm mô hình dữ liệu, API backend, giao diện và tương tác frontend, ghép nối frontend với backend.\\n\\nTheo tiêu chí nghiệm thu, chạy test backend, test và build frontend thật của dự án, cùng kịch bản end-to-end các luồng chính. Lỗi nhỏ thì sửa và chạy lại; lỗi liên quan cả hai phía hoặc cần sửa lớn thì nộp rework để trả về «Ghép nối». Ghi lệnh, mã thoát, kết quả và phần chưa kiểm được vào test-report.md.\\n\\nHoàn thành phần việc của bước này và nộp đủ sản phẩm đã quy định. Viết tài liệu và báo cáo bằng tiếng Việt có dấu.\\n\\n### Đầu vào\\n\\n- Yêu cầu: {{input}}\\n- Repo: {{repository}}", "skills": [], "version": 1, "updatedAt": "2026-11-21T00:00:00Z", "executorId": "claude", "mcpServers": []}, {"id": "generic-fullstack-delivery-mr", "name": "Mở MR/PR", "rules": ["generic-fullstack-engineering"], "prompt": "Phạm vi: tính năng fullstack, gồm mô hình dữ liệu, API backend, giao diện và tương tác frontend, ghép nối frontend với backend.\\n\\nNghiệm thu đã đạt. Bước này commit thay đổi của lần chạy vào nhánh làm việc, push và mở MR/PR; không sửa nghiệp vụ nữa.\\n\\n1. Chưa gắn repo: không push, không tạo MR/PR. Ghi vào mr-body.md «Chưa gắn repo, mã nguồn giữ trong workspace của run» kèm danh sách file bàn giao, rồi nộp pass.\\n2. Đã gắn repo: xử lý lần lượt từng thư mục checkout; repo nào không có thay đổi thì bỏ qua, không tạo MR/PR rỗng. Kiểm đang ở nhánh làm việc của lần chạy, không commit lên nhánh chính, không chuyển hay tạo nhánh mới; xem git status và diff, chỉ commit thay đổi mã nguồn thuộc việc này, không commit .agentflow, thư mục dependency, sản phẩm build và tài liệu của các bước SOP; commit với message tóm tắt thay đổi, rồi git push -u origin <nhánh làm việc hiện tại>. Nền tảng đã cấp thông tin xác thực Git; không in, không hiển thị, không ghi token ra bất cứ đâu.\\n3. Mở MR/PR vào nhánh đích ghi trong thông tin repo: dùng CLI của nền tảng (gh, glab) hoặc MCP đã cấu hình, có thể tra API chính thức của nền tảng. Gọi API cần token thì lấy bằng git credential fill theo host của repo, chỉ giữ trong bộ nhớ tiến trình. Nhánh làm việc đã có MR/PR vào cùng nhánh đích thì cập nhật nó, không tạo trùng.\\n4. Tiêu đề tóm tắt thay đổi; mô tả gồm tóm tắt yêu cầu, điểm thay đổi chính, kết quả test (theo test-report.md) và giới hạn đã biết, viết bằng tiếng Việt. Không merge MR/PR, không push lên nhánh chính, không force push.\\n5. Ghi link MR/PR, nhánh nguồn, nhánh đích và SHA commit của từng repo vào mr-body.md.\\n6. Push hoặc tạo MR/PR thất bại (thiếu thông tin xác thực, không có quyền, lỗi mạng…) thì không được nộp pass: ghi lý do vào mr-body.md, nộp human và ghi trong actionRequired việc người cần làm, ví dụ cấu hình Git token rồi chạy lại, hoặc tự mở MR trên nền tảng.\\n\\nRàng buộc MR: {{existingMR}}\\n\\nHoàn thành phần việc của bước này và nộp đủ sản phẩm đã quy định. Viết tài liệu và báo cáo bằng tiếng Việt có dấu.\\n\\n### Đầu vào\\n\\n- Yêu cầu: {{input}}\\n- Repo: {{repository}}", "skills": [], "version": 1, "updatedAt": "2026-11-21T00:00:00Z", "executorId": "claude", "mcpServers": [], "loop": {"enabled": true, "onExhausted": "human", "exitCondition": "all_gates_pass", "maxIterations": 2}, "verification": [{"id": "mr-pushed", "mode": "command", "name": "Thay đổi đã commit và push", "stage": "after_execution", "commands": ["fail=0\\ntab=\\"$(printf ''\\\\t'')\\"\\nwhile IFS=\\"$tab\\" read -r d work base; do\\n  [ -n \\"$d\\" ] || continue\\n  dirty=\\"$(git -C \\"$d\\" status --porcelain --untracked-files=all -- . \\":(exclude).agentflow\\" \\":(exclude,glob)**/node_modules/**\\")\\" || { printf \\"%s không phải thư mục Git checkout dùng được\\\\n\\" \\"$d\\"; fail=1; continue; }\\n  if [ -n \\"$dirty\\" ]; then printf \\"%s còn thay đổi chưa commit:\\\\n%s\\\\n\\" \\"$d\\" \\"$dirty\\"; fail=1; continue; fi\\n  refs=HEAD\\n  if git -C \\"$d\\" rev-parse -q --verify \\"refs/heads/$work\\" >/dev/null; then refs=\\"HEAD refs/heads/$work\\"; fi\\n  ahead=\\"$(git -C \\"$d\\" rev-list --count $refs --not \\"refs/remotes/origin/$base\\")\\" || { printf \\"%s không tìm thấy nhánh đích origin/%s\\\\n\\" \\"$d\\" \\"$base\\"; fail=1; continue; }\\n  [ \\"$ahead\\" != 0 ] || continue\\n  branch=\\"$(git -C \\"$d\\" branch --show-current)\\"\\n  if [ \\"$branch\\" != \\"$work\\" ]; then printf \\"%s đang ở %s, không ở nhánh làm việc %s của lần chạy này\\\\n\\" \\"$d\\" \\"${branch:-HEAD tách rời}\\" \\"$work\\"; fail=1; continue; fi\\n  head=\\"$(git -C \\"$d\\" rev-parse HEAD)\\"\\n  pushed=\\"$(git -C \\"$d\\" ls-remote origin \\"refs/heads/$work\\")\\" || { printf \\"%s không đọc được remote origin\\\\n\\" \\"$d\\"; fail=1; continue; }\\n  if [ \\"${pushed%%\\"$tab\\"*}\\" != \\"$head\\" ]; then printf \\"%s: nhánh làm việc %s trên origin không trỏ tới %s, commit của lần chạy này chưa được push\\\\n\\" \\"$d\\" \\"$work\\" \\"$head\\"; fail=1; fi\\ndone <<EOF\\n$AGENTFLOW_WORK_BRANCHES\\nEOF\\nexit \\"$fail\\""], "required": true, "onFailure": "loop", "executionScope": "run"}, {"id": "mr-opened", "mode": "mr", "name": "Đã mở MR/PR", "stage": "after_execution", "required": true, "onFailure": "loop"}]}, {"id": "generic-fullstack-delivery-deliver", "name": "Tổng hợp bàn giao", "rules": ["generic-fullstack-engineering"], "prompt": "Phạm vi: tính năng fullstack, gồm mô hình dữ liệu, API backend, giao diện và tương tác frontend, ghép nối frontend với backend.\\n\\nĐối chiếu sản phẩm thực tế và bằng chứng kiểm chứng của từng bước, ghi vào delivery.md: nội dung đã làm, kết quả test thật, giới hạn đã biết và danh sách sản phẩm bàn giao. Chưa gắn repo thì bàn giao mã nguồn và báo cáo trong workspace của run, không cần Git token. Code đã được bước «Mở MR/PR» commit, push và mở MR/PR: lấy link, nhánh và SHA commit trong mr-body.md đưa vào danh sách bàn giao; bước này không sửa code, không push, không tạo PR, không merge.\\n\\nHoàn thành phần việc của bước này và nộp đủ sản phẩm đã quy định. Viết tài liệu và báo cáo bằng tiếng Việt có dấu.\\n\\n### Đầu vào\\n\\n- Yêu cầu: {{input}}\\n- Repo: {{repository}}", "skills": [], "version": 1, "updatedAt": "2026-11-21T00:00:00Z", "executorId": "claude", "mcpServers": []}], "Skills": [], "Workflow": {"version": 1, "updatedAt": "2026-11-21T00:00:00Z", "id": "generic-fullstack-delivery", "name": "SOP chuẩn · Phát triển fullstack", "revision": 1, "status": "published", "description": "Yêu cầu fullstack đi từ chốt yêu cầu, thiết kế hợp đồng API, làm backend và frontend song song, ghép nối, review độc lập, kiểm thử, nghiệm thu đến mở MR/PR và bàn giao. Mọi bước chạy bằng Claude Code.", "sandboxProfileId": "generic-docker", "generic": true, "owner": "LoopForge", "tags": ["public"], "nodes": [{"id": "clarify", "name": "Chốt yêu cầu", "type": "agent", "agentId": "generic-fullstack-delivery-clarify", "maxAttempts": 2, "metricStage": "clarification", "artifactOutputs": [{"name": "clarify", "path": "requirement.md", "required": true, "mediaType": "text/markdown"}], "position": {"x": 100, "y": 200}}, {"id": "design", "name": "Thiết kế giải pháp", "type": "agent", "agentId": "generic-fullstack-delivery-design", "maxAttempts": 2, "metricStage": "clarification", "artifactOutputs": [{"name": "design", "path": "design.md", "required": true, "mediaType": "text/markdown"}], "position": {"x": 345, "y": 200}}, {"id": "backend", "name": "Làm backend", "type": "agent", "agentId": "generic-fullstack-delivery-backend", "maxAttempts": 2, "metricStage": "development", "artifactOutputs": [{"name": "backend", "path": "backend.md", "required": true, "mediaType": "text/markdown"}], "position": {"x": 590, "y": 100}}, {"id": "frontend", "name": "Làm frontend", "type": "agent", "agentId": "generic-fullstack-delivery-frontend", "maxAttempts": 2, "metricStage": "development", "artifactOutputs": [{"name": "frontend", "path": "frontend.md", "required": true, "mediaType": "text/markdown"}], "position": {"x": 590, "y": 300}}, {"id": "integrate", "name": "Ghép nối", "type": "agent", "agentId": "generic-fullstack-delivery-integrate", "maxAttempts": 2, "metricStage": "development", "artifactOutputs": [{"name": "integrate", "path": "integration.md", "required": true, "mediaType": "text/markdown"}], "position": {"x": 835, "y": 200}, "maxReworks": 2}, {"id": "review", "name": "Review độc lập", "type": "agent", "agentId": "generic-fullstack-delivery-review", "maxAttempts": 2, "metricStage": "testing", "artifactOutputs": [{"name": "review", "path": "review.md", "required": true, "mediaType": "text/markdown"}], "position": {"x": 1080, "y": 200}, "rejectTo": "integrate", "onFai